            if i + 1 <= N:
                moves.append(i + 1)
            if 2 * i <= N:
                moves.append(2 * i)

            # win[i] is True if there is a move to a False state
            for m in moves:
                if win[m] == False:
                    win[i] = True
                    break
            else:
                win[i] = False

    # Player A writes 1.
    # Now it's Player B's turn to move from 1.
    # If win[1] is True, B wins. If win[1] is False, A wins.
    return "A" if win[1] == False else "B"

